class Solution:
    def applySubstitutions(self, replacements: List[List[str]], text: str) -> str:
        mp = dict(replacements)
        memo = {}
        def resolve(k):
            if k in memo:
                return memo[k]
            v = mp[k]
            out = []
            i = 0
            while i < len(v):
                if v[i] == '%':
                    j = v.index('%', i + 1)
                    out.append(resolve(v[i + 1:j]))
                    i = j + 1
                else:
                    out.append(v[i]); i += 1
            memo[k] = ''.join(out)
            return memo[k]
        out = []
        i = 0
        while i < len(text):
            if text[i] == '%':
                j = text.index('%', i + 1)
                out.append(resolve(text[i + 1:j]))
                i = j + 1
            else:
                out.append(text[i]); i += 1
        return ''.join(out)

