class Solution {
public:
    string applySubstitutions(vector<vector<string>>& replacements, string text) {
        unordered_map<string, string> mp, memo;
        for (auto& r : replacements) mp[r[0]] = r[1];
        function<string(const string&)> res = [&](const string& k) -> string {
            auto it = memo.find(k);
            if (it != memo.end()) return it->second;
            const string& v = mp[k];
            string out; size_t i = 0;
            while (i < v.size()) {
                if (v[i] == '%') {
                    size_t j = v.find('%', i + 1);
                    out += res(v.substr(i + 1, j - i - 1));
                    i = j + 1;
                } else out += v[i++];
            }
            return memo[k] = out;
        };
        string out; size_t i = 0;
        while (i < text.size()) {
            if (text[i] == '%') {
                size_t j = text.find('%', i + 1);
                out += res(text.substr(i + 1, j - i - 1));
                i = j + 1;
            } else out += text[i++];
        }
        return out;
    }
};

