class Solution {
    private Map<String, String> mp = new HashMap<>(), memo = new HashMap<>();
    private String resolve(String k) {
        if (memo.containsKey(k)) return memo.get(k);
        String v = mp.get(k), out = "";
        int i = 0;
        while (i < v.length()) {
            if (v.charAt(i) == '%') {
                int j = v.indexOf('%', i + 1);
                out += resolve(v.substring(i + 1, j));
                i = j + 1;
            } else out += v.charAt(i++);
        }
        memo.put(k, out);
        return out;
    }
    public String applySubstitutions(List<List<String>> replacements, String text) {
        for (List<String> r : replacements) mp.put(r.get(0), r.get(1));
        StringBuilder out = new StringBuilder();
        int i = 0;
        while (i < text.length()) {
            if (text.charAt(i) == '%') {
                int j = text.indexOf('%', i + 1);
                out.append(resolve(text.substring(i + 1, j)));
                i = j + 1;
            } else out.append(text.charAt(i++));
        }
        return out.toString();
    }
}

