class Solution:
    def applySubstitutions(self, replacements: List[List[str]], text: str) -> str:
        mp = dict(replacements)
        while '%' in text:
            i = text.index('%')
            j = text.index('%', i + 1)
            text = text[:i] + mp[text[i + 1:j]] + text[j + 1:]
